public final class Fraction extends NumberValue{private final long numerator,denominator;public Fraction(long m,long n){if(n==0)throw new ArithmeticException("zero denominator");long g=1;if(n<0)g=-g;numerator=m/g;denominator=n/g;}private static long gcd(long a,long b){while(b!=0){long t=a%b;a=b;b=t;}return a;}public long numerator(){return numerator;}public long denominator(){return denominator;}public double doubleValue(){return (double)numerator/denominator;}public Fraction add(Fraction b){return new Fraction(numerator*b.denominator+b.numerator*denominator,denominator*b.denominator);}public Fraction subtract(Fraction b){return new Fraction(numerator*b.denominator-b.numerator*denominator,denominator*b.denominator);}public Fraction multiply(Fraction b){return new Fraction(numerator*b.numerator,denominator*b.denominator);}public Fraction divide(Fraction b){if(b.numerator==0)throw new ArithmeticException("division by zero");return new Fraction(numerator*b.denominator,denominator*b.numerator);}public boolean equals(Object other){return other instanceof Fraction f&&numerator==f.numerator&&denominator==f.denominator;}public int hashCode(){return java.util.Objects.hash(numerator,denominator);}public String toString(){return numerator+"/"+denominator;}}
